<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import SiteHeader from '../components/SiteHeader.vue';
import SiteFooter from '../components/SiteFooter.vue';
import Icon from '../components/Icon.vue';
import { getPetById } from '../services/petApi.js';
import { api } from '../services/api.js';
import { currentUser, loadCurrentUser } from '../services/auth.js';

const route = useRoute(); const router = useRouter(); const pet = ref(null); const records = ref([]); const loading = ref(true); const saving = ref(false); const error = ref(''); const notice = ref('');
const form = reactive({ recordType: 'VACCINATION', title: '', description: '', performedAt: new Date().toISOString().slice(0, 10), nextDueAt: '', veterinarianName: '' });
const canEdit = computed(() => currentUser.value?.role === 'SHELTER' || currentUser.value?.role === 'ADMIN');
const typeLabels = { VACCINATION: 'Vacunación', DEWORMING: 'Desparasitación', STERILIZATION: 'Esterilización', MEDICAL_CONSULTATION: 'Consulta médica', TREATMENT: 'Tratamiento', OTHER: 'Otro' };
async function load() { const id = String(route.query.pet || ''); if (!id) { error.value = 'No se indicó una mascota.'; loading.value = false; return; } loading.value = true; error.value = ''; try { await loadCurrentUser(); pet.value = await getPetById(id); records.value = await api(`/pets/${id}/health-records`); } catch (failure) { error.value = failure.status === 401 ? 'Inicia sesión para consultar el expediente sanitario.' : failure.message || 'No se pudo cargar el expediente sanitario.'; } finally { loading.value = false; } }
async function save() { if (saving.value || !pet.value) return; saving.value = true; error.value = ''; notice.value = ''; try { await api(`/pets/${pet.value.id}/health-records`, { method: 'POST', body: { ...form, nextDueAt: form.nextDueAt || null, description: form.description.trim() || null, veterinarianName: form.veterinarianName.trim() || null } }); notice.value = 'Registro sanitario guardado.'; form.title = ''; form.description = ''; form.nextDueAt = ''; form.veterinarianName = ''; records.value = await api(`/pets/${pet.value.id}/health-records`); } catch (failure) { error.value = failure.message || 'No se pudo guardar el registro.'; } finally { saving.value = false; } }
onMounted(load);
</script>
<template>
  <div class="health-page"><SiteHeader /><main class="health-main"><div class="health-heading"><div><p class="eyebrow">BIENESTAR Y CUIDADO</p><h1>Expediente sanitario</h1><p v-if="pet">Historial de {{ pet.name }}. Mantén sus cuidados documentados y sus próximas fechas visibles.</p></div><button class="health-back" type="button" @click="router.back()"><Icon name="arrow-left" />Volver</button></div><p v-if="loading" class="health-state" role="status">Cargando expediente…</p><p v-else-if="error" class="health-state health-error" role="alert">{{ error }}</p><template v-else><section class="health-layout"><section class="health-panel"><div class="health-panel-heading"><div><h2>Registros</h2><p>{{ records.length }} registrados</p></div><span v-if="pet" class="health-pet-name">{{ pet.name }}</span></div><p v-if="!records.length" class="health-empty">Todavía no hay registros sanitarios.</p><ol v-else class="health-list"><li v-for="record in records" :key="record.id"><span class="health-record-icon"><Icon name="badge-check" /></span><div><div class="health-record-title"><strong>{{ record.title }}</strong><span>{{ typeLabels[record.recordType] || record.recordType }}</span></div><p v-if="record.description">{{ record.description }}</p><small>Realizado: {{ new Date(`${record.performedAt}T12:00:00`).toLocaleDateString('es-MX') }}<template v-if="record.nextDueAt"> · Próximo: {{ new Date(`${record.nextDueAt}T12:00:00`).toLocaleDateString('es-MX') }}</template><template v-if="record.veterinarianName"> · {{ record.veterinarianName }}</template></small></div></li></ol></section><section v-if="canEdit" class="health-panel"><h2>Agregar registro</h2><form class="health-form" @submit.prevent="save"><label>Tipo<select v-model="form.recordType"><option v-for="(label,value) in typeLabels" :key="value" :value="value">{{ label }}</option></select></label><label>Título<input v-model="form.title" maxlength="180" required placeholder="Ej. Vacuna antirrábica"></label><label>Fecha<input v-model="form.performedAt" type="date" required></label><label>Próxima fecha<input v-model="form.nextDueAt" type="date"></label><label>Veterinario<input v-model="form.veterinarianName" maxlength="160"></label><label class="health-wide">Descripción<textarea v-model="form.description" maxlength="4000" rows="4"></textarea></label><p v-if="notice" class="health-notice" role="status">{{ notice }}</p><button class="health-submit" type="submit" :disabled="saving">{{ saving ? 'Guardando…' : 'Guardar registro' }}</button></form></section></section></template></main><SiteFooter /></div>
</template>
<style scoped>
.health-page{min-height:100vh;background:var(--background)}.health-main{width:min(1120px,calc(100% - 40px));margin:0 auto;padding:45px 0 75px}.health-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;margin-bottom:25px}.health-heading h1{margin:8px 0;color:var(--text);font:800 clamp(1.9rem,4vw,3rem)/1.1 "Poppins",sans-serif}.health-heading p:last-child{margin:0;color:var(--text-soft);line-height:1.6}.health-back{display:inline-flex;align-items:center;gap:7px;min-height:40px;padding:0 12px;border:1px solid var(--border);border-radius:10px;background:var(--white);color:var(--primary-strong);cursor:pointer;font-weight:800}.health-back :deep(svg){width:16px}.health-layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr);gap:18px}.health-panel{padding:23px;border:1px solid var(--border);border-radius:17px;background:var(--white)}.health-panel h2{margin:0;color:var(--text);font:750 1.15rem "Poppins",sans-serif}.health-panel-heading{display:flex;justify-content:space-between;gap:14px;padding-bottom:15px;border-bottom:1px solid var(--border)}.health-panel-heading p{margin:4px 0 0;color:var(--text-soft);font-size:.74rem}.health-pet-name{color:var(--primary-strong);font-weight:800}.health-empty,.health-state{padding:35px 12px;color:var(--text-soft);text-align:center}.health-list{display:grid;gap:0;margin:0;padding:0;list-style:none}.health-list li{display:grid;grid-template-columns:38px minmax(0,1fr);gap:11px;padding:16px 0;border-bottom:1px solid var(--border)}.health-record-icon{display:grid;width:34px;height:34px;place-items:center;border-radius:10px;background:#e8f6f5;color:var(--primary-strong)}.health-record-icon :deep(svg){width:17px}.health-record-title{display:flex;align-items:center;justify-content:space-between;gap:10px}.health-record-title strong{color:var(--text);font-size:.86rem}.health-record-title span{color:var(--primary-strong);font-size:.65rem;font-weight:800}.health-list p{margin:7px 0;color:var(--text-soft);font-size:.76rem;line-height:1.5}.health-list small{color:var(--text-soft);font-size:.67rem}.health-form{display:grid;gap:12px;margin-top:17px}.health-form label{display:grid;gap:6px;color:var(--text);font-size:.73rem;font-weight:750}.health-form input,.health-form select,.health-form textarea{width:100%;min-height:42px;padding:9px 11px;border:1px solid var(--border);border-radius:9px;background:var(--background);color:var(--text);font:500 .8rem "Montserrat",sans-serif}.health-form textarea{resize:vertical}.health-wide{grid-column:1/-1}.health-submit{min-height:42px;border:0;border-radius:10px;background:var(--primary-strong);color:#fff;cursor:pointer;font-weight:800}.health-submit:disabled{opacity:.65;cursor:wait}.health-notice{margin:0;color:#287451;font-size:.75rem}.health-error{color:var(--danger)}@media(max-width:760px){.health-main{width:calc(100% - 28px);padding:30px 0 50px}.health-heading{flex-direction:column}.health-layout{grid-template-columns:1fr}.health-panel{padding:18px}.health-record-title{align-items:flex-start;flex-direction:column;gap:3px}}
</style>
